parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "engine_oil_with_filter_l",
    "transmission_l",
    "front_diff_l",
    "rear_diff_l",
    "transfer_case_l",
    "coolant_l",
    "brake_fluid_l",
    "sources",
    "confidence",
    "notes"
  ],
  "properties": {
    "engine_oil_with_filter_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Engine oil capacity with filter change. Litres, or null if not found."
    },
    "transmission_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Transmission fluid capacity (drain and refill for automatics). Litres, or null if not found."
    },
    "front_diff_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Front differential oil. Litres, or null if not found."
    },
    "rear_diff_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Rear differential oil. Litres, or null if not found."
    },
    "transfer_case_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Transfer case oil. Litres, or null if not found."
    },
    "coolant_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Cooling system capacity. Litres, or null if not found."
    },
    "brake_fluid_l": {
      "type": [
        "number",
        "null"
      ],
      "description": "Brake fluid for a full change. Litres, or null if not found."
    },
    "sources": {
      "type": "array",
      "maxItems": 8,
      "items": {
        "type": "string"
      },
      "description": "Links to the pages the numbers were taken from."
    },
    "confidence": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high"
      ]
    },
    "notes": {
      "type": "string",
      "maxLength": 500,
      "description": "Кратка бележка на български за собственика: какво е несигурно."
    }
  }
}
